import numpy as np
from sklearn.kernel_ridge import KernelRidge
from sklearn.decomposition import PCA

class AsinhKRR:
    def __init__(self, p=None, seed=0):
        p = dict(p or {})
        self.p = p
        self.c = float(p.get('c', 3.0)) * float(p.get('sigma', 1e-3))
        self.npc = int(p.get('pca', 40))
        self.alphas = list(p.get('alphas', [1e-4, 1e-3, 1e-2]))
        self.gms = list(p.get('gamma_mults', [0.1, 0.3, 1.0]))
        self.lo = float(p.get('lo', 0.5))
        self.hi = float(p.get('hi', 2.0))
        self.seed = int(seed) if seed is not None else 0

    def get_params(self, deep=True):
        return {'p': self.p, 'seed': self.seed}

    def set_params(self, **kw):
        if 'p' in kw:
            self.__init__(kw['p'], kw.get('seed', self.seed))
        elif 'seed' in kw:
            self.seed = int(kw['seed'])
        return self

    def _feat(self, X, fit):
        X = np.nan_to_num(np.asarray(X, float), nan=0.0, posinf=0.0, neginf=0.0)
        Z = np.arcsinh(X / self.c)
        if fit:
            self.mu = Z.mean(0)
            self.sd = Z.std(0) + 1e-12
        Z = (Z - self.mu) / self.sd
        if fit:
            k = max(1, min(self.npc, Z.shape[1], Z.shape[0] - 1))
            self.pca = PCA(n_components=k, random_state=0).fit(Z)
        return self.pca.transform(Z)

    # y may arrive already standardised by the harness (negative values), so log
    # is only used when targets are strictly positive.
    def _fwd(self, y):
        return np.log(y) if self.logm else y

    def _inv(self, t):
        v = np.exp(np.clip(t, -50, 50)) if self.logm else t
        return np.clip(v, self.ylo, self.yhi)

    def fit(self, X, y):
        y = np.asarray(y, float)
        self.one_d = (y.ndim == 1)
        if self.one_d:
            y = y[:, None]
        F = self._feat(X, True)
        self.logm = bool(np.all(np.isfinite(y)) and y.min() > 0)
        inb = y.min() >= self.lo - 1e-9 and y.max() <= self.hi + 1e-9
        if inb:
            self.ylo, self.yhi = self.lo, self.hi
        else:
            span = y.max(0) - y.min(0)
            self.ylo = y.min(0) - 0.05 * span
            self.yhi = y.max(0) + 0.05 * span
        T = self._fwd(y)
        self.tm = T.mean(0)
        Tc = T - self.tm
        base = 1.0 / (F.shape[1] * F.var() + 1e-12)
        n = len(F)
        perm = np.random.RandomState(self.seed).permutation(n)
        nh = max(n // 5, 1)
        h, r = perm[:nh], perm[nh:]
        yh = y[h]
        best = (np.inf, self.alphas[0], self.gms[0])
        for a in self.alphas:
            for g in self.gms:
                try:
                    m = KernelRidge(alpha=a, kernel='rbf', gamma=g * base).fit(F[r], Tc[r])
                    pr = self._inv(m.predict(F[h]).reshape(len(h), -1) + self.tm)
                    e = np.linalg.norm(pr - yh) / (np.linalg.norm(yh) + 1e-12)
                except Exception:
                    e = np.inf
                if np.isfinite(e) and e < best[0]:
                    best = (e, a, g)
        self.sel = best
        self.m = KernelRidge(alpha=best[1], kernel='rbf', gamma=best[2] * base).fit(F, Tc)
        return self

    def predict(self, X):
        F = self._feat(X, False)
        P = self.m.predict(F).reshape(len(F), -1) + self.tm
        out = self._inv(P)
        return out[:, 0] if self.one_d else out

def build_model(params, task, seed):
    return AsinhKRR(params, seed)
